"""Regenerate the retained 0.1.0 compatibility fixtures from the 0.1.0 release source.

Run once with the *0.1.0* package installed (source commit ``0da1249``), never with
the current one; see README.md in this directory for the exact commands. The output is
historical data: later servers are tested against it, it is never regenerated by them.

Everything is synthetic: reserved example hosts, a mock transport, a fixed clock and
an in-process MCP client. Nothing contacts the network.
"""

from __future__ import annotations

import argparse
import json
import shutil
import sys
import tempfile
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

import anyio
import httpx2 as httpx
from mcp.client import Client

import wled_mcp
from wled_mcp.backups import Firmware, SnapshotStore
from wled_mcp.config import load_config
from wled_mcp.operations import build_operations
from wled_mcp.resources import Resources
from wled_mcp.server import create_server

RELEASE = "0.1.0"
CREATED = datetime(2026, 11, 6, 12, 0, 0, tzinfo=UTC)
FIRMWARE_VERSION = "16.0.1"
INFO: dict[str, Any] = {
    "ver": FIRMWARE_VERSION,
    "vid": 2510010,
    "brand": "WLED",
    "product": "FOSS",
    "arch": "esp32",
    "name": "Example",
    "leds": {"count": 60, "maxseg": 32, "lc": 1, "seglc": [1, 1]},
    "fxcount": 3,
    "palcount": 2,
}
STATE: dict[str, Any] = {
    "on": True,
    "bri": 128,
    "transition": 7,
    "ps": -1,
    "pl": -1,
    "mainseg": 0,
    "seg": [
        {"id": 0, "start": 0, "stop": 30, "on": True, "bri": 255, "col": [[255, 160, 0]]},
        {"id": 1, "start": 30, "stop": 60, "on": False, "bri": 90, "col": [[0, 0, 255]]},
    ],
}
PRESET: dict[str, Any] = {
    "n": "Saved scene",
    "on": True,
    "bri": 180,
    "seg": [{"id": 1, "start": 30, "stop": 60, "col": [[255, 80, 0]], "fx": 1}],
    "vendor_extension": {"opaque_value": ["preserved", 1.5, None]},
}


def dump(path: Path, value: Any) -> None:
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", "utf-8", newline="\n")


def device(request: httpx.Request) -> httpx.Response:
    routes = {"/json/info": INFO, "/json/state": STATE}
    return httpx.Response(200, json=routes[request.url.path])


async def generate(source: Path, output: Path) -> None:
    if wled_mcp.__version__ != RELEASE:
        raise SystemExit(f"run with the {RELEASE} package, found {wled_mcp.__version__}")
    output.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(source / "examples" / "devices.example.toml", output / "config.toml")
    with tempfile.TemporaryDirectory() as temporary:
        data_dir = Path(temporary)
        config = load_config(str((output / "config.toml").resolve()), str(data_dir))

        store = SnapshotStore(data_dir / "backups", 20, lambda: CREATED)
        record = store.backup_preset("desk", 5, PRESET, Firmware(FIRMWARE_VERSION, 2510010))
        # Stored as ``snapshots/`` because ``backups/`` is ignored by Git; the tests copy
        # it into ``<data dir>/backups/`` as the 0.1.0 server would have laid it out.
        snapshots = output / "snapshots" / "desk"
        shutil.rmtree(output / "snapshots", ignore_errors=True)
        snapshots.mkdir(parents=True)
        written = data_dir / "backups" / "desk" / f"{record.backup_id}.json"
        shutil.copyfile(written, snapshots / written.name)

        async with Resources(config, httpx.MockTransport(device)) as resources:
            async with Client(create_server(build_operations(resources))) as client:
                tools = (await client.list_tools()).tools
                served = [
                    tool.model_dump(mode="json", by_alias=True, exclude_none=True) for tool in tools
                ]
                result = await client.call_tool("wled_get_state", {"device_id": "desk"})
    envelope = result.structured_content
    if envelope is None or not envelope.get("ok"):
        raise SystemExit(f"wled_get_state failed: {envelope}")
    envelope["data"]["freshness"]["read_at"] = CREATED.isoformat()  # wall clock otherwise
    dump(output / "tools.json", served)
    dump(output / "get_state.json", envelope)
    print(f"Wrote {len(served)} tools, 1 snapshot and 1 envelope to {output}", file=sys.stderr)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--source", type=Path, required=True, help="0.1.0 source tree.")
    parser.add_argument("--output", type=Path, required=True, help="Fixture directory.")
    args = parser.parse_args()
    anyio.run(generate, args.source.resolve(), args.output.resolve())
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
